int main(){mgt_cuda::CudaMlpShape s{2,4,3,2,1,1};mgt::BatchNormTrainingPlan p;if(mgt::BuildBatchNormTrainingPlan(3,2,3,2,1,4,&p)!=mgt::Status::kOk)return 1;auto bn=mgt::InitializeBatchNormTrainingState(p);std::uint64_t params=50;std::vector<float>w(params);for(std::size_t i=0;i<w.size();i++)w[i]=.03f*static_cast<float>(static_cast<int>(i%9)-4);mgt::TrainStateStorage states[4]{};for(unsigned r=0;r<4;r++){states[r].v[0]=r;states[r].v[1]=(r+1)%4;}float labels[4]={1.f,3.f,-1.f,2.f};float *dw,*da,*dr,*dout,*dwork,*dlabels,*dloss,*dgrad,*ddy,*dfinal,*daffgrad,*dfc1,*dresidual;cudaMalloc(&dw,w.size()*sizeof(float));cudaMalloc(&da,bn.affine.size()*sizeof(float));cudaMalloc(&dr,bn.running.size()*sizeof(float));cudaMalloc(&dout,4*sizeof(float));auto wf=mgt_cuda::MlpBatchNormForwardWorkspaceFloats(s,p,4);cudaMalloc(&dwork,wf*sizeof(float));cudaMalloc(&dlabels,sizeof(labels));cudaMalloc(&dloss,sizeof(float));cudaMalloc(&dgrad,params*sizeof(float));cudaMalloc(&ddy,4*sizeof(float));cudaMalloc(&dfinal,8*sizeof(float));cudaMalloc(&daffgrad,bn.affine.size()*sizeof(float));cudaMalloc(&dfc1,8*sizeof(float));cudaMalloc(&dresidual,8*sizeof(float));cudaMemcpy(dw,w.data(),w.size()*sizeof(float),cudaMemcpyHostToDevice);cudaMemcpy(da,bn.affine.data(),bn.affine.size()*sizeof(float),cudaMemcpyHostToDevice);cudaMemcpy(dr,bn.running.data(),bn.running.size()*sizeof(float),cudaMemcpyHostToDevice);cudaMemcpy(dlabels,labels,sizeof(labels),cudaMemcpyHostToDevice);cudaMemset(dgrad,0,params*sizeof(float));cudaMemset(daffgrad,0,bn.affine.size()*sizeof(float));mgt::TrainStateStorage* ds;cudaMalloc(&ds,sizeof(states));cudaMemcpy(ds,states,sizeof(states),cudaMemcpyHostToDevice);mgt_cuda::NcclRankContext*ctx=nullptr;cublasHandle_t blas=nullptr;if(mgt_cuda::CreateNcclSingleRankContext(0,&ctx)!=mgt::Status::kOk||cublasCreate(&blas)!=CUBLAS_STATUS_SUCCESS)return 1;if(mgt_cuda::LaunchMlpBatchNormForward(s,3,2,dw,da,dr,ds,4,4,dout,dwork,wf,p,ctx,blas,0)!=mgt::Status::kOk)return 1;float*final_activation=dwork+4*s.hd1+static_cast<std::uint64_t>(s.residual_blocks)*4*s.hd2;if(mgt_cuda::LaunchMlpBatchNormOutputLossGrad(s,dw,dlabels,dout,final_activation,4,4,dloss,dgrad,ddy,dfinal,ctx,blas,0)!=mgt::Status::kOk)return 1;if(mgt_cuda::LaunchMlpBatchNormResidualStackBackward(s,dw,da,4,4,dwork,p,dfinal,dgrad,daffgrad,dfc1,dresidual,ctx,blas,0)!=mgt::Status::kOk||cudaDeviceSynchronize()!=cudaSuccess)return 1;float grad[12]{},ag[8]{};cudaMemcpy(grad,dgrad+35,12*sizeof(float),cudaMemcpyDeviceToHost);cudaMemcpy(ag,daffgrad+5,4*sizeof(float),cudaMemcpyDeviceToHost);cudaMemcpy(ag+4,daffgrad+14,4*sizeof(float),cudaMemcpyDeviceToHost);const float expected_grad[12]={.0307231583f,.0001711696f,.0306863356f,.0001709908f,-5.9604645e-8f,3.7252903e-9f,-.4785869718f,.3933217525f,.1560483873f,-.1997075081f,-8.9406967e-8f,-4.8428774e-8f};const float expected_ag[8]={.0092416974f,-.0099205412f,-.0463866517f,-.0727168843f,.0101242792f,-.0045198090f,.0047413092f,.0623136088f};for(int i=0;i<12;i++)if(std::fabs(grad[i]-expected_grad[i])>5e-5f)return 1;for(int i=0;i<8;i++)if(std::fabs(ag[i]-expected_ag[i])>5e-5f)return 1;cublasDestroy(blas);return mgt_cuda::DestroyNcclRankContext(ctx)==mgt::Status::kOk?0:1;}